  "implementation": "def solve(case):
    segments = case.get('segments')
    budget = case.get('budget')
    if not isinstance(segments, list) or len(segments) == 0:
        raise ValueError('segments must be a non-empty list')
    if not isinstance(budget, int):
        raise ValueError('budget must be an integer')
    allocations = []
    sum_min = 0
    sum_cap = 0
    for s in segments:
        name = s.get('name')
        importance = s.get('importance')
        minimum = s.get('minimum')
        capacity = s.get('capacity')
        if not isinstance(name, str) or not isinstance(importance, int) or not isinstance(minimum, int) or not isinstance(capacity, int):
            raise ValueError('invalid segment fields')
        if minimum < 0 or capacity < minimum:
            raise ValueError('invalid minimum or capacity')
        allocations.append(minimum)
        sum_min += minimum
        sum_cap += capacity
    if budget < sum_min:
        raise ValueError('budget below total minimum quota')
    if budget > sum_cap:
        raise ValueError('budget above total capacity')
    remaining = budget - sum_min
    while remaining > 0:
        best_idx = None
        best_score = float('-inf')
        for i, s in enumerate(segments):
            if allocations[i] < s['capacity']:
                score = s['importance'] / (allocations[i] + 1)
                if score > best_score or (score == best_score and (best_idx is None or i < best_idx)):
                    best_score = score
                    best_idx = i
        if best_idx is None:
            # Should not happen if constraints hold, but guard
            break
        allocations[best_idx] += 1
        remaining -= 1
    by_name = {segments[i]['name']: allocations[i] for i in range(len(segments))}
    total = sum(allocations)
    return {'allocations': allocations, 'by_name': by_name, 'total': total}
